pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 2 ether);
        uint256 initBalance = c.getBalance(alice); // 0
        // overflow: max uint256 + 1 => require catches this
        uint256 overflowValue = type(uint256).max - initBalance + 1;
        vm.prank(alice);
        // In reference contract, require fails -> revert; in mutant, it passes
        try c.addToBalance{value: overflowValue}() {
            // no revert: mutant case
            uint256 newBalance = c.getBalance(alice);
            assertTrue(newBalance != type(uint256).max);
        } catch {
            // revert: reference case
            assertTrue(c.getBalance(alice) == 0);
        }
    }
}

