contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);

        // Give alice enough ether to cause overflow when adding to balance
        vm.deal(alice, 1 ether);

        // First, alice calls addToBalance with a value that will cause overflow later
        // We want to set alice's balance to 1 first, then add type(uint256).max to overflow
        vm.prank(alice);
        c.addToBalance{value: 1}();

        // Now increment alice's balance by a value that, when added, will overflow
        // Since current balance is 1, we need to add type(uint256).max - 1 + 1 = type(uint256).max?
        // Actually to overflow: 1 + x must wrap around. We'll add type(uint256).max - 1
        vm.prank(alice);
        c.addToBalance{value: type(uint256).max - 1}();

        // Now alice's balance is 0 (1 + type(uint256).max - 1 = type(uint256).max, which overflows to 0 in the buggy version)
        // In the reference, the second addToBalance reverts because of overflow check
        // But we need to check bob's balance instead, as per the hint

        // Instead use a different approach: make alice's balance large, then call addToBalance with a huge value
        // to trigger overflow revert in reference, but not in mutant

        // Reset: deploy new contract
        c = new C();

        // Give alice 1 wei to start
        vm.deal(alice, 1 wei);
        vm.prank(alice);
        c.addToBalance{value: 1}();

        // Now try to add type(uint256).max wei from alice (but we need to give enough ether)
        vm.deal(alice, type(uint256).max);

        vm.prank(alice);
        // This call will revert in reference (overflow check), but not in mutant
        c.addToBalance{value: type(uint256).max}();

        // In reference, this line should never be reached because previous call reverts
        // In mutant, alice's balance becomes 0 (1 + type(uint256).max wraps to 0)

        // Get bob's balance — should be 0 always
        uint256 bobBalance = c.getBalance(bob);

        // The assertion: in the reference, the previous call reverts so we never get here;
        // but since we're writing a test that must pass on reference, we need to catch the revert
        // Let's restructure with try/catch

        c = new C();
        vm.deal(alice, 1 wei);
        vm.prank(alice);
        c.addToBalance{value: 1}();

        bool ok;
        vm.deal(alice, type(uint256).max);
        vm.prank(alice);
        try c.addToBalance{value: type(uint256).max}() {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference, it reverts (ok == false); in mutant it succeeds (ok == true)
        // We assert ok == false, which reference satisfies
        assertTrue(!ok);
    }
}

